/* Video Player front end.
 *
 * Talks to the native host (host/src/main.cpp) through WebView2:
 *   page -> host  chrome.webview.postMessage({cmd, reqId?, ...})
 *     open {path, startMs, paused?} · play · pause · toggle · seek {ms} · seekRelative {ms} · stop
 *     releaseSurface (mpv: hide the video window; sent after the exit transition, stop leaves it up)
 *     selectSubtitle {index} · loadSubtitle {path} · pickSubtitle
 *     fullscreen {on?} · getConfig · setConfig {text, restartAudio} · scan · loadData {key} · saveData {key, text}
 *     pickFile · pickFolder · listAsio · listWasapi · restartAudio · audioStatus · devtools
 *   host -> page  {type, reqId?, ...}
 *     player {event: opened|state|firstFrame|position|clock|error|surface|ended|subtitle, data}
 *       state "playing" means decoding started (mpv FILE_LOADED), not that a picture is visible;
 *       firstFrame (mpv only) = the first frame of the loaded file is on screen and the video
 *       window was just shown. The player keeps its black curtain up until then (8 s fallback).
 *       While an open replaces a playing file, mpv sends opening (never stopped) and keeps the old picture.
 *     fullscreen {on, pending?}: pending:true comes before the window resizes, then {on} after it
 *     replies carry the request's reqId
 *
 * Library data comes from scanning the folders in config.json until the metadata
 * database (another agent's work) is connected: titles, seasons and episodes are
 * parsed from file and folder names; artwork is a generated gradient.
 * Without the host (plain browser) the page runs on demo data for UI work.
 */
'use strict';

// ===================================================================== bridge
const host = window.chrome && window.chrome.webview ? window.chrome.webview : null;
const pending = new Map();
let reqSeq = 1;
const listeners = { player: [], fullscreen: [], thumb: [] };

function send(cmd, args = {}) {
  // LAN client page (lan.js): data over HTTP from the server, playback local or in <video>.
  if (window.LAN && LAN.mode === 'remote' && LAN.send(cmd, args)) return;
  if (host) host.postMessage(Object.assign({ cmd }, args));
  else Demo.handle(Object.assign({ cmd }, args));
}
function call(cmd, args = {}) {
  return new Promise((resolve) => {
    const reqId = reqSeq++;
    pending.set(reqId, resolve);
    send(cmd, Object.assign({ reqId }, args));
  });
}
function receive(message) {
  if (!message || typeof message !== 'object') return;
  if (message.reqId && pending.has(message.reqId)) {
    const resolve = pending.get(message.reqId);
    pending.delete(message.reqId);
    resolve(message);
    return;
  }
  if (message.type === 'player') listeners.player.forEach((fn) => fn(message.event, message.data || {}));
  if (message.type === 'fullscreen') listeners.fullscreen.forEach((fn) => fn(!!message.on, !!message.pending));
  if (message.type === 'thumb') listeners.thumb.forEach((fn) => fn(message));
  if (message.type === 'artwork') (listeners.artwork || []).forEach((fn) => fn(message));
  if (message.type === 'diagnostics') onDiagnostics(message);
  if (message.type === 'gpuAdapterStatus') onGpuAdapterStatus(message);
}
if (host) host.addEventListener('message', (event) => receive(event.data));

// ===================================================================== helpers
const $ = (selector, root = document) => root.querySelector(selector);
const esc = (value) => String(value ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const pad = (n) => (n < 10 ? '0' : '') + n;
function clock(ms) {
  const s = Math.max(0, Math.floor((ms || 0) / 1000));
  return Math.floor(s / 3600) + ':' + pad(Math.floor(s / 60) % 60) + ':' + pad(s % 60);
}
function minutesLeft(ms) { return Math.max(1, Math.round(ms / 60000)); }
function hash(text) {
  let h = 2166136261;
  for (let i = 0; i < text.length; i++) { h ^= text.charCodeAt(i); h = Math.imul(h, 16777619); }
  return h >>> 0;
}
function basename(path) { return String(path).split(/[\\/]/).pop(); }
function stemOf(name) { return name.replace(/\.[^.]+$/, ''); }
function fmtSize(bytes) {
  if (!bytes) return '';
  const gb = bytes / 1073741824;
  return gb >= 1 ? gb.toFixed(gb >= 10 ? 0 : 1) + ' GB' : Math.round(bytes / 1048576) + ' MB';
}
function ago(ms) {
  if (!ms) return '';
  const days = Math.floor((Date.now() - ms) / 86400000);
  if (days <= 0) return '今天';
  if (days === 1) return '昨天';
  if (days < 7) return days + ' 天前';
  if (days < 30) return Math.floor(days / 7) + ' 週前';
  const d = new Date(ms);
  return d.getFullYear() + '/' + pad(d.getMonth() + 1) + '/' + pad(d.getDate());
}
const KIND_HUE = { movie: 212, series: 160, live: 28 };
function art(seed, kind, light = 66, dark = 32) {
  const base = (KIND_HUE[kind] ?? 212) + ((hash(seed) % 70) - 35);
  return 'linear-gradient(160deg, hsl(' + base + ' 70% ' + light + '%), hsl(' + (base + 30) + ' 55% ' + dark + '%))';
}
let toastTimer = 0;
let toastWait = null; // cancels the wait for the exit animation
const recentToasts = new Map(); // text -> time shown; the same message is not repeated within 15 s
// One toast at a time: a new one first lets the shown one leave (--d-fast), then enters (--d-base).
// action: optional { label, run } shown as a button inside the toast (e.g. 「開啟資料夾」 after a diagnostics export).
function toast(text, ms = 3200, action = null) {
  const now = Date.now();
  if (now - (recentToasts.get(text) || 0) < 15000) return;
  recentToasts.set(text, now);
  const el = $('#toast');
  clearTimeout(toastTimer);
  const show = () => {
    el.textContent = text;
    if (action) {
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'toast-act';
      button.textContent = action.label;
      button.addEventListener('click', (event) => { event.stopPropagation(); action.run(); toastOut(el); });
      el.append(button);
    }
    el.classList.remove('out');
    el.hidden = false;
    el.style.animation = 'none'; void el.offsetWidth; el.style.animation = ''; // replay the entrance
    toastTimer = setTimeout(() => toastOut(el), ms);
  };
  if (!el.hidden && !el.classList.contains('out')) toastOut(el, show);
  else if (!el.hidden && toastWait) toastOut(el, show); // already leaving: show this one after it
  else show();
}
function toastOut(el, then) {
  if (toastWait) toastWait();
  el.classList.add('out');
  toastWait = afterMotion(el, motionMs('fast'), () => {
    toastWait = null;
    el.hidden = true;
    el.classList.remove('out');
    if (then) then();
  }, (event) => event.animationName === 'm-toast-out');
}

// 匯出診斷資料 (mpv edition): the host writes data\diagnostics\vp-diag-<time>.zip on a worker thread and reports
// progress as {type:'diagnostics', state:'start'|'done'|'error', path}. Buttons: 處理環境 and the info-panel footer.
let diagExporting = false;
function diagButton(cls) {
  return '<button type="button" class="' + cls + '" data-action="export-diagnostics"' + (diagExporting ? ' disabled' : '') + '>' +
    (diagExporting ? '匯出中…' : '匯出診斷資料') + '</button>';
}
function setDiagButtons() {
  document.querySelectorAll('[data-action="export-diagnostics"]').forEach((button) => {
    button.disabled = diagExporting;
    button.textContent = diagExporting ? '匯出中…' : '匯出診斷資料';
  });
}
function exportDiagnostics() {
  if (diagExporting) return;
  // the last 刷新全部中繼資料 summaries ride along with the request (ui.metaRefresh); see the refresh report for the host side
  call('exportDiagnostics', { ui: { metaRefresh: RF.log.slice(-5) } }).then((reply) => {
    if (reply && !reply.ok && reply.reason === 'demo') toast('示範模式無法匯出診斷資料');
  });
}
function onDiagnostics(message) {
  if (message.state === 'start') {
    diagExporting = true;
    setDiagButtons();
    recentToasts.delete('正在匯出診斷資料…');
    toast('正在匯出診斷資料…', 60000);
    return;
  }
  diagExporting = false;
  setDiagButtons();
  if (message.state === 'done') {
    toast('已匯出：' + message.path, 10000, { label: '開啟資料夾', run: () => call('openRuntimeFolder', { what: 'diagnostics' }).then((reply) => {
      if (!reply || !reply.ok) toast('無法開啟資料夾' + (reply && reply.path ? '：' + reply.path : ''), 5000);
    }) });
  } else if (message.state === 'error') {
    toast('匯出診斷資料失敗：' + (message.message || message.reason || '未知錯誤'), 8000);
  }
}

