  const scanned = new Map((scan || []).map((lib) => [lib.id, lib.files || []]));
  S.libs = (S.config?.libraries || []).map((cfg) => {
    const files = scanned.get(cfg.id) || [];
    const lib = { id: cfg.id, name: cfg.name || cfg.id, kind: cfg.kind || 'movie', folders: cfg.folders || [], items: [], episodes: [] };
    if (lib.kind === 'series') buildSeries(lib, files); else buildMovies(lib, files);
    lib.items.forEach((item) => item.episodes.forEach((ep) => { S.byPath.set(ep.path, { lib, item, ep }); lib.episodes.push(ep); }));
    return lib;
  });
