    const edge = (list, p, field) => list.find((e) => e.p === p && e.f === field) || null;
    const seasonEdges = (fs) => (byFrom.get('s:' + id + '#' + fs) || []).filter((e) => e.k === 'season-chain');
    const rec = {};
