  const work = (p) => { const e = mine.find((x) => x.from === 'w:' + id && x.k === 'id-link' && x.p === p); return e ? e.to : null; };
  const workAl = work('al'), workBgm = work('bgm'), workTmdb = work('tmdb');
  const media = graphObj(st.media) ? st.media : {};
  const seasons = [...new Set(mine.filter((e) => e.from.startsWith(pre)).map((e) => +e.from.slice(pre.length)))];
  const it = Array.isArray(item.seasons) ? item : Object.assign({}, item, { seasons });
  const ws = alWorkSeason(it, workAl ? media[+workAl.slice(3)] || null : null);
  const cell = (fs, p) => mine.find((e) => e.from === pre + fs && e.k === 'season-chain' && e.p === p && !e.via) || null;
  const out = [];
