  if (had && jsonSame(r.graph, codes) && !Object.keys(add).length) return false;
  const patch = { review: { flags: [...new Set([...(r.flags || []), 'graph-conflict'])], graph: codes, graphAt: now } };
  if (Object.keys(add).length) patch.prov = { seasonLinks: provSeasonLinksWith(m, add) };
  matchWrite(item.id, patch, { by: 'reverify-graph' });
