      const r = await httpCall('api.bgm.tv', method, path, body ? JSON.stringify(body) : '', token ? 'Authorization: Bearer ' + token : '');
      if (breakerSeen('bgm', r)) { if (breakerHeld('bgm')) break; continue; }
