  try { if (found && !found.summary) found = Object.assign(found, (await bgmSubject(found.id)) || {}); } catch (error) { console.warn('bangumi', error); return alBackoffNote(item.id + '|bgm', fetchFailKind(error)); }
  if (!found && failed) return alBackoffNote(item.id + '|bgm', failed);
