// ---- 刷新全部中繼資料 (settings 線上資料): the items of the libraries that use online data, in library order.
function refreshTargets() {
  const out = [];
  for (const lib of S.libs || []) if (alLibEnabled(lib)) for (const item of lib.items || []) out.push(item);
  return out;
}
// The confirmation's estimate: items x the requests each provider would get, from the cache and the switches (entries two
