    const plan = refreshPlan(item, store, Object.assign({}, ctx, { seen }));
    if (plan.skip) { out.skip[plan.skip] = (out.skip[plan.skip] || 0) + 1; if (plan.skip === 'all-locked') out.lockedSeasons += plan.locked.length; continue; }
    out.items++;
