window.addEventListener('pagehide', () => { RF.closing = true; if (RF.all) RF.all.cancel = true; }); // app closing: stop before the next request
// Phase 3B: the episode's own src first
function alEpisode(item, ep) { return epovUses(item, ep, 'al') ? alEpisodeRaw(item, ep) : null; }
function alEpisodeRaw(item, ep) {
  if (epovByNumberOff(item, ep)) return null; // Phase 3B: a marked episode is not looked up by number
  const m = alSeasonMedia(item, ep.fileSeason ?? ep.season);
  if (!m || !m.streamingEpisodes || !m.streamingEpisodes.length) return null;
  const n = ep.fileEpisode ?? ep.episode;
  for (const e of m.streamingEpisodes) {
    const hit = String(e.title || '').match(/^Episode\s*(\d+)\s*[-–:]\s*(.+)$/i);
    if (hit && +hit[1] === n) return { title: hit[2].trim(), thumbnail: e.thumbnail || '' };
  }
  return null;
}
function alPlainText(html) {
  if (!html) return '';
  const text = new DOMParser().parseFromString(String(html).replace(/<br\s*\/?>/gi, '\n'), 'text/html').body.textContent || '';
  return text.replace(/\n{3,}/g, '\n\n').replace(/\s*\((?:Source|來源)[^)]*\)\s*$/i, '').trim();
}
function staffRoleZh(role) {
  for (const [re, zh] of STAFF_ROLE_ZH) if (re.test(role || '')) return zh;
  return '';
}
// AniList characters (with their Japanese voice actor) and staff (roles named in Chinese) of one entry (work or season).
function alCredits(m) {
  const cast = (m.characters?.edges || []).map((e) => ({
    role: e.role,
    character: { id: e.node?.id, name: e.node?.name?.native || e.node?.name?.full || '', alt: e.node?.name?.full || '', image: e.node?.image?.medium || '' },
    person: e.voiceActors?.[0] ? { id: e.voiceActors[0].id, name: e.voiceActors[0].name?.native || e.voiceActors[0].name?.full || '', alt: e.voiceActors[0].name?.full || '', image: e.voiceActors[0].image?.medium || '' } : null,
  }));
  const crew = [];
  for (const e of m.staff?.edges || []) {
    const zh = staffRoleZh(e.role);
    if (!zh || crew.some((c) => c.id === e.node.id && c.role === zh)) continue;
    crew.push({ id: e.node.id, name: e.node.name?.native || e.node.name?.full || '', alt: e.node.name?.full || '', image: e.node.image?.medium || '', role: zh });
  }
  return { cast, crew };
}
function alToMeta(m, bgm, item) {
  const { cast, crew } = alCredits(m);
  const tmdb = item ? tmdbOf(item) : null;
  const zhPlot = pickChinese(tmdb && tmdb.overview, bgm && bgm.summary ? zhTw(bgm.summary.trim()) : '');
  const crt = (bgm && bgm.crt) || [];
  for (const c of cast) {
    const hit = crt.find((x) => x.name && normCJK(x.name) === normCJK(c.character.name));
    if (hit && hit.name_cn) { c.character.cn = toTw(hit.name_cn); }
  }
  return {
    kind: 'anilist', ids: { anilist: String(m.id), mal: m.idMal ? String(m.idMal) : '', bangumi: bgm ? String(bgm.id) : '' },
    title: '', originaltitle: m.title?.native || m.title?.romaji || '', chineseTitle: bgm && bgm.name_cn ? toTw(bgm.name_cn) : '',
    plot: zhPlot || alPlainText(m.description), plotSource: !zhPlot ? 'AniList（英文）' : tmdb && zhPlot === tmdb.overview ? 'TMDB' : 'Bangumi',
    year: alYear(m), genres: (m.genres || []).map((g) => GENRE_ZH[g] || g),
    alScore: m.averageScore || null, bgmScore: bgm && bgm.score ? bgm.score : null, studio: m.studios?.nodes?.[0]?.name || '',
    runtime: m.format === 'MOVIE' ? m.duration : null, directors: crew.filter((c) => c.role === '導演').map((c) => c.name),
    cast, crew, actors: [],
    isAdult: !!m.isAdult, format: m.format, episodes: m.episodes,
  };
}

// ---------------------------------------------------------------- match dialog
