  const size = fmtSize((item.episodes || []).reduce((sum, e) => sum + (+e.size || 0), 0));
  const text = (mediaProbeCache.has(ep.path) ? fileInfoTag(mediaProbeCache.get(ep.path)) : '讀取格式…') + (size ? ' · ' + size : '');
  return '<span class="al-badge file-badge" data-file-info="' + esc(ep.path) + '" data-size="' + esc(size) + '" title="' + esc(basename(ep.path)) + '">' + esc(text) + '</span>';
