    const tag = kind === 'review' ? alReviewShort(r.flag) : kind === 'choice' ? p2CandLine(r.cands) : '資料集建議' + (n > 1 ? ' ' + n : '');
    const keep = lanRemote() ? '' : kind === 'review'
