// hasKana, kanaCount and isJapaneseText all read it).
//   kana      letters only: hiragana U+3041-3096, katakana U+30A1-30FA, half-width katakana U+FF66-FF6F and
//             U+FF71-FF9D. Not ・ (U+30FB), ー (U+30FC), ｰ (U+FF70) or the sound marks: Chinese uses ・ in names.
//   'ja'      kana >= 6 and kana / length > 0.06 (the old rule and ratio, on letters only); a short text (< 60 characters
//             without spaces) also with >= 2 hiragana (M2 P5; conservative: katakana alone in a short text is usually
//             a name inside Chinese, so it does not count)
//   'zh'      Han characters and not Japanese; 'und' instead when the Han characters include Japanese-only forms
//             (剣 転 様 …: shinjitai neither Traditional nor Simplified Chinese uses) and no Chinese function word
//             (的 了 這 們 …): kana-free Japanese is not taken for Chinese and not converted by OpenCC
//   'en'      Latin letters (>= 3) and no Han / kana; otherwise 'und'
// -> {lang, script: 'Jpan' | 'Hani' | 'Latn' | 'und', confidence: 'high' | 'medium' | 'low'}
const LANG_SHORT = 60;
function langStats(text) {
  const s = String(text || '');
  const count = (re) => (s.match(re) || []).length;
  return { len: s.replace(/\s/g, '').length, total: s.length, hira: count(/[ぁ-ゖ]/g), kana: count(/[ぁ-ゖァ-ヺｦ-ｯｱ-ﾝ]/g),
    han: count(/\p{Script=Han}/gu), latin: count(/[A-Za-z]/g),
    jaOnly: count(/[剣転県円駅戦気広歳読図帰楽発変様歩険処拡継続絵黒闘隠薬単弾営栄覚権関駆験済挿鉄伝徳仏辺塩沢浜桜斎竜亜悪圧囲壊懐巻歓観犠拠挙暁勲経渓軽鶏撃検厳効鉱砕剤雑賛桟歯児釈収従渋獣縦粛奨焼渉乗剰浄畳譲醸粋酔髄瀬斉摂専銭荘捜巣総騒増臓蔵対帯滝択団遅鋳庁聴逓稲弐悩脳廃売髪抜晩払豊穂黙訳揺頼覧両猟涙塁戻霊齢暦歴労]/g),
    zhWord: count(/[的了這这們们個个說说沒没嗎吗呢她它還还讓让從从吧啊哪裡么麼]/g) };
}
