const EPOV_KIND_NAME = { recap: '總集篇', special: '特別篇', absent: '資料庫沒有這一集' };
const EPOV_SRC_NAME = { auto: '自動', tmdb: 'TMDB', bgm: 'Bangumi', al: 'AniList', local: '只用本機檔案' };
const EPOV_ONLY_NOTE = '只改這一集，不會改變本季的位移';
// The labels after an episode's label (detail page, LAN): its mark, and 已自訂 when it has its own title, synopsis,
