  const E = (n) => 'E' + pad(n);
  const off = (n) => '位移 ' + (n > 0 ? '+' : '') + (n || 0);
  if (ov && ov.kind === 'absent') return '不使用資料庫（資料庫沒有這一集）';
  const src = ov && ov.src ? ov.src : seasonSrc(item, fs);
  const uses = (k) => src === 'auto' || src === k;
  if (src === 'local') return '只用本機檔案' + (ov && ov.src ? ' · 這一集指定' : '');
  if (ov && ov.map && ov.map.tmdb && uses('tmdb')) { const t = ov.map.tmdb; return 'TMDB ' + t.id + ' 第 ' + t.season + ' 季 ' + E(t.ep) + ' · 指定（絕對）' + (epovTmdbData(item, t) ? '' : '（資料尚未下載）'); }
  if (ov && ov.map && ov.map.bgm && uses('bgm')) { const b = ov.map.bgm; return 'Bangumi ' + b.id + ' ' + E(b.ep) + ' · 指定（絕對）' + (epovBgmData(item, b) ? '' : '（資料尚未下載）'); }
  if (ov && ov.kind) return EPOV_KIND_NAME[ov.kind] + ' · 不依集數查找';
  if (uses('tmdb') && tmdbReadable()) {
    const ref = seasonTmdbRef(item, fs);
    if (ref) return 'TMDB 第 ' + ref.season + ' 季 ' + E(fe + (ref.offset || 0)) + ' · 自動（' + off(ref.offset) + '）';
  }
  if (uses('bgm') && alPrefs().chinese) {
    const c = seasonCfgEff(item, fs) || {};
    const m = alMatch(item);
    const id = c.bgm ? c.bgm.id : m && m.seasonBgm && m.seasonBgm[fs];
    const o = c.bgm ? c.bgm.offset || 0 : 0;
    if (id) return 'Bangumi ' + id + ' ' + E(fe + o) + ' · 自動（' + off(o) + '）';
  }
  if (uses('al')) { const m = alSeasonMedia(item, fs); if (m) return 'AniList ' + m.id + ' ' + E(fe) + ' · 自動'; }
