  if (btn && !btn.classList.contains('syn-more-btn')) btn = null;
  const open = el.classList.contains('open');
  if (el.dataset.synKey) { if (open) openSyn.add(el.dataset.synKey); else openSyn.delete(el.dataset.synKey); }
  if (!open && el.scrollHeight <= el.clientHeight + 1) { if (btn) btn.remove(); return; }
  // the same button is kept across patches (it may have the focus)
  if (!btn) { btn = document.createElement('button'); btn.type = 'button'; btn.dataset.action = 'syn-toggle'; btn._morphKeep = true; el.after(btn); }
  btn.className = 'syn-more-btn' + (open ? ' open' : '');
