let clampResizeTimer = 0;
window.addEventListener('resize', () => { clearTimeout(clampResizeTimer); clampResizeTimer = setTimeout(() => markClamps($('#view')), 200); });
// Poster titles get two lines; a title that still does not fit becomes one line that scrolls
// (marquee) while its card is hovered or focused.
