    const names = [item.title, item.fileTitle, item.parsed && item.parsed.title, item.meta && item.meta.originaltitle].filter(Boolean).map((t) => t.toLowerCase());
    if (names.some((t) => t.includes(q)) || item.episodes.some((e) => e.file.toLowerCase().includes(q) || (e.title || '').toLowerCase().includes(q))) hits.push(posterCard(lib, item));
