    !shaders.some((entry) => video.upscaleMode === 'glsl:' + entry.id);
  const upLabel = video.upscaleMode === 'off' ? '關閉' : upscaleUnavailable ? '目前不可用'
    : dmlSelected ? ((models.find((row) => 'dml:' + row.file === video.upscaleMode) || {}).label || stemOf(video.upscaleMode.slice(4)))
    : ((shaders.find((entry) => 'glsl:' + entry.id === video.upscaleMode) || {}).label || video.upscaleMode.slice(5));
