  const rifeNames = { '46': 'RIFE v4.6', '4251': 'RIFE v4.25 lite', '426': 'RIFE v4.26', '4262': 'RIFE v4.26 heavy' };
  const rifeChoices = Object.keys(rifeNames).map((id) => [id, rifeNames[id] + (rifeV2.includes(rifeFile[id]) ? '' : '（尚未安裝）'), !rifeV2.includes(rifeFile[id])]);
  // k7sfunc loads only the ensemble export for v4.6 quality; no plain rife\rife_v4.6.onnx is needed.
