  const options = (values, current) => values.map(([value, text, disabled]) => '<option value="' + esc(value) + '"' +
    (String(current) === String(value) ? ' selected' : '') + (disabled ? ' disabled' : '') + '>' + esc(text) + '</option>').join('');
  // The control column of the 音訊 page: every select the same width; the slot after it stays empty here.
